/bin/bash -lc "cd [workspace path] && python3 -c \"
import numpy as np
a = np.load('source_pixels.npz')['rgb'].astype(int)
def redcent(t):
    f=a[t]; r,g,b=f[...,0],f[...,1],f[...,2]
    m=(r>160)&(g<130)&(b<130)&(r-g>40)&(r-b>40)
    return m
# track red blob regions over time via centroid in fixed windows
wins={'topleft':(0,60,0,90),'topmid':(85,130,0,15),'bottom':(130,160,115,144),'rightedge':(240,256,45,60)}
for name,(x0,x1,y0,y1) in wins.items():
    print('==',name)
    for t in range(0,96,6):
        m=redcent(t)
        sub=np.zeros_like(m); sub[y0:y1,x0:x1]=m[y0:y1,x0:x1]
        yy,xx=np.where(sub)
        if len(xx): print(t,len(xx),round(xx.mean(),1),round(yy.mean(),1),xx.min(),xx.max(),yy.min(),yy.max())
        else: print(t,0)
\""
